    else{need(s.isFile()&&s.nlink===1n&&!ids.has(s.dev+':'+s.ino),'ordinary distinct payload');ids.add(s.dev+':'+s.ino);files.push(n)}
  }}walk(base);return {files:files.sort(),directories:directories.sort()};
